'use client';

import * as DialogPrimitive from '@radix-ui/react-dialog';
import type { ReactElement } from 'react';

import { cn } from '../../lib/cn';

import type {
  DialogCloseProps,
  DialogContentProps,
  DialogDescriptionProps,
  DialogFooterProps,
  DialogHeaderProps,
  DialogOverlayProps,
  DialogPortalProps,
  DialogProps,
  DialogTitleProps,
  DialogTriggerProps,
} from './dialog.types';

/* Generated by the shadcn CLI (new-york-v4 `dialog`), then rewired: its palette
 * is replaced with Vows tokens and its enter and leave animations, which need a
 * plugin this repository does not carry, are gone. The Radix behaviour — focus
 * trap, Escape, scroll lock, hiding the page behind — is untouched. */

/* Two shadows, as the Figma component draws them: 0 2 6 at 7 per cent and
 * 0 20 48 −14 at 20 per cent. `Elevation/modal` is a different, single shadow. */
const lift =
  'shadow-[0_2px_6px_0_color-mix(in_srgb,var(--vows-color-ink-900)_7%,transparent),0_20px_48px_-14px_color-mix(in_srgb,var(--vows-color-ink-900)_20%,transparent)]';

export function Dialog(props: DialogProps): ReactElement {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />;
}

export function DialogTrigger(props: DialogTriggerProps): ReactElement {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />;
}

export function DialogPortal(props: DialogPortalProps): ReactElement {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />;
}

export function DialogClose(props: DialogCloseProps): ReactElement {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />;
}

export function DialogOverlay({ className, ...props }: DialogOverlayProps): ReactElement {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn('bg-scrim/62 fixed inset-0 z-50', className)}
      {...props}
    />
  );
}

/* 440 wide and centred from the tablet up. Below 640 it is the full width less
 * 24 either side and sits 16 above the bottom edge. */
export function DialogContent({
  className,
  children,
  container,
  ...props
}: DialogContentProps): ReactElement {
  return (
    <DialogPortal container={container}>
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          'inset-x-space-6 bottom-space-4 border-hairline bg-surface fixed z-50 flex flex-col rounded-[10px] border outline-none',
          'tablet:inset-x-auto tablet:top-1/2 tablet:bottom-auto tablet:left-1/2 tablet:w-[440px] tablet:-translate-x-1/2 tablet:-translate-y-1/2',
          lift,
          className,
        )}
        {...props}
      >
        {children}
      </DialogPrimitive.Content>
    </DialogPortal>
  );
}

export function DialogHeader({ className, ...props }: DialogHeaderProps): ReactElement {
  return (
    <div
      data-slot="dialog-header"
      className={cn('gap-space-3 flex items-center', className)}
      {...props}
    />
  );
}

export function DialogFooter({ className, ...props }: DialogFooterProps): ReactElement {
  return (
    <div
      data-slot="dialog-footer"
      className={cn('flex items-center justify-end gap-[10px]', className)}
      {...props}
    />
  );
}

export function DialogTitle({ className, ...props }: DialogTitleProps): ReactElement {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn('type-studio-title text-heading', className)}
      {...props}
    />
  );
}

export function DialogDescription({ className, ...props }: DialogDescriptionProps): ReactElement {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn('type-studio-body text-secondary', className)}
      {...props}
    />
  );
}
